h"},{"sheet":"Emily George","row":182,"text":"Cleaning kitchen (sweeping out entire room, mopping, making sure sink is clean, wiping down all stainless steel, organizing)","category":"Group Letouts","reason":"no_canonical_task_match"},{"sheet":"Emily George","row":183,"text":"Wiping down tops of executive rooms (what to use)","category":"Group Letouts","reason":"no_canonical_task_match"},{"sheet":"Emily George","row":184,"text":"Wipe down lockers in 200s hallway (what to use)","category":"Group Letouts","reason":"no_canonical_task_match"},{"sheet":"Emily George","row":185,"text":"Clean Parking Lot (pick up trash, change poop trash bag outside and refill as needed, foam parking lot/sidewalk)","category":"Group Letouts","reason":"no_canonical_task_match"},{"sheet":"Emily George","row":186,"text":"Deep Clean Compartments (push out all compartments sweep and mop behind them as well as sweeping and mopping entire hallway, clean and organize/restock cleaning supplies in hallway, dust top of compartments)","category":"Group Letouts","reason":"no_canonical_task_match"},{"sheet":"Emily George","row":187,"text":"Polish metal throughout building (kickplates, door handles, what to use)","category":"Group Letouts","reason":"no_canonical_task_match"},{"sheet":"Emily George","row":188,"text":"Magic Erase walls and columns in lux hallway (scooter, where and what to use)","category":"Group Letouts","reason":"no_canonical_task_match"},{"sheet":"Emily George","row":189,"text":"Scrub bottom of executive rooms (scooter, what to use)","category":"Group Letouts","reason":"no_canonical_task_match"},{"sheet":"Emily George","row":190,"text":"Sanitize PP toys (bringing whole bin into grooming and utilizing one of the tubs rinsing all of the toys with water and spraying everything with resuce, rinsing thoroughly and making sure bin and toys are dry before putting back)","category":"Group Letouts","reason":"no_canonical_task_match"}],"note_like_verifier_values":[{"sheet":"Addison Earnest","row":76,"task":"After all disinfects or whenever done with the cleaning cart making sure to properly clean it up. Dumping bucket for water bowls and putting empty bowls in the sink. Removing trash bag from the cart and disposing of it in the dumpster, rinsing out disinfect bucket and putting back in the mop closet, wringing out sponge and putting it in dirty laundry.","value":"?"},{"sheet":"Evelyn Guevara Flores","row":5,"task":"Timeout Procedure (how long a dog can be in the gate, how to make notes to 700s, how to fill out timeout card, make sure notes go on whiteboard, behaviors that warrant a t/o, how to handle a timecheck, making sure PCTs always have a lead on them","value":"not making notes via walkie"},{"sheet":"Evelyn Guevara Flores","row":6,"task":"Daycare Tech (how to spot clean inside of daycare)","value":"lacks and is slow to p/u"},{"sheet":"Evelyn Guevara Flores","row":9,"task":"How to clear the gate (how to utilize shields and red board to clear the gate, always help fellow pct, call dogs out to yard to get them away from gate)","value":"Zach C says she struggles with this portion"},{"sheet":"Evelyn Guevara Flores","row":10,"task":"Cleaning the yard (picking up after the dogs as soon as possible and as frequently as possible, making sure before you rotate the yard is clean for the pcts coming in, using the hose to clean stains and rolling the hose back up, replacing poop bags on holders once the last of them are used)","value":"needs to be more on top of it"},{"sheet":"Evelyn Guevara Flores","row":41,"task":"1. Gathering Supplies on cleaning cart (sponge, disinfect bucket from mop closet, windex, paper towels, squeegee, blue bucket on cleaning cart or empty bucket for water bowls, broom, trash bag on cart","value":"moves too fast quality is not great"},{"sheet":"Evelyn Guevara Flores","row":42,"task":"2. Remove and empty water bowl","value":"moves too fast quality is not great"},{"sheet":"Evelyn Guevara Flores","row":43,"task":"3. Breakdown couch and scrub each individual piece with the sponge from the bucket of rescue.","value":"moves too fast quality is not great"},{"sheet":"Evelyn Guevara Flores","row":44,"task":"4. Scrub each individual wall with rescue and sponge as well as the entire inside of the door (making sure not to use rescue on any of the paint)","value":"moves too fast quality is not great"},{"sheet":"Evelyn Guevara Flores","row":45,"task":"5. Scrub outside of the lux door with rescue and sponge (careful not to let excess rescue sit on outside of gold door it will strip the paint)","value":"moves too fast quality is not great"},{"sheet":"Evelyn Guevara Flores","row":46,"task":"6. Squeegee glass inside and outside.","value":"moves too fast quality is not great"},{"sheet":"Evelyn Guevara Flores","row":47,"task":"7. Windex glass inside and outside","value":"moves too fast quality is not great"},{"sheet":"Evelyn Guevara Flores","row":48,"task":"8. Mop entire room with disinfect mop bucket and resweep as needed","value":"moves too fast quality is not great"},{"sheet":"Evelyn Guevara Flores","row":49,"task":"9. Remove run card and file properly in the kitchen","value":"moves too fast quality is not great"},{"sheet":"Evelyn Guevara Flores","row":50,"task":"10. Sign initials on report under the room number that was just completed.","value":"moves too fast quality is not great"},{"sheet":"Evelyn Guevara Flores","row":53,"task":"1. Gathering Supplies on cleaning cart (sponge, disinfect bucket from mop closet, windex, paper towels, squeegee, blue bucket on cleaning cart or empty bucket for water bowls, broom, trash bag on cart","value":"needs work not great quality"},{"sheet":"Evelyn Guevara Flores","row":54,"task":"2. Remove and empty water bowl.","value":"needs work not great quality"},{"sheet":"Evelyn Guevara Flores","row":55,"task":"3. Sweep out entire room and make sure to get excess hair off of the bed.","value":"needs work not great quality"},{"sheet":"Evelyn Guevara Flores","row":56,"task":"4. Scrub entire room both inside and outside with sponge and rescue, hitting all four walls focusing on corners and crevices especially (making sure not to use rescue on any of the paint)","value":"needs work not great quality"},{"sheet":"Evelyn Guevara Flores","row":57,"task":"5. Scrub all glass with sponge and rescue.","value":"needs work not great quality"},{"sheet":"Evelyn Guevara Flores","row":58,"task":"6. Squeegee all glass","value":"needs work not great quality"},{"sheet":"Evelyn Guevara Flores","row":59,"task":"7. Windex all glass with paper towels","value":"needs work not great quality"},{"sheet":"Evelyn Guevara Flores","row":60,"task":"8. Mop entire room with disinfect mop bucket and resweep as needed, also making sure there is no excess hair anywhere","value":"needs work not great quality"},{"sheet":"Evelyn Guevara Flores","row":61,"task":"9. Remove run card and file properly in the kitchen","value":"needs work not great quality"},{"sheet":"Evelyn Guevara Flores","row":62,"task":"10. Sign initials on report under the room number that was just completed.","value":"needs work not great quality"},{"sheet":"Lahayla Kern","row":33,"task":"How to properly use boxes (making sure all dogs are secured in each box with carabiner prior to leaving them unattended in the yard, making sure when using boxes no PP dogs interact at all, going into the box to put the lead on the dog prior to removing them frm the box","value":"Julia Z (confirmed instructions with her)"}],"verifier_name_typo_candidates":[{"value":"Allison D","count":122,"possible_match":"Allison D.","possible_match_count":23,"ratio":1.0},{"value":"Angelina D","count":800,"possible_match":"Angleina D","possible_match_count":1,"ratio":0.889},{"value":"Angelina D","count":800,"possible_match":"Anglelina D","possible_match_count":1,"ratio":0.947},{"value":"Angleina D","count":1,"possible_match":"Anglelina D","possible_match_count":1,"ratio":0.947}]}}'::jsonb;
  v_template_id uuid := (v_seed->'template'->>'id')::uuid;
  v_version_id uuid := (v_seed->'template'->>'version_id')::uuid;
  v_section jsonb;
  v_item jsonb;
  v_trainee jsonb;
  v_result jsonb;
  v_section_id uuid;
  v_item_id uuid;
  v_record_id uuid;
  v_employee public.labor_employees%ROWTYPE;
  v_employee_id uuid;
  v_match_count integer := 0;
  v_match_report jsonb := jsonb_build_object('matched', '[]'::jsonb, 'unmatched', '[]'::jsonb, 'ambiguous', '[]'::jsonb);
  v_required_count integer := 0;
BEGIN
  INSERT INTO public.training_templates (
    id,
    slug,
    name,
    template_class,
    role_scopes,
    location_id,
    is_active
  )
  VALUES (
    v_template_id,
    v_seed->'template'->>'slug',
    v_seed->'template'->>'name',
    'training_plan',
    ARRAY['pct', 'pet_care_technician'],
    NULL,
    true
  )
  ON CONFLICT (slug) DO UPDATE
  SET
    name = EXCLUDED.name,
    role_scopes = EXCLUDED.role_scopes,
    is_active = true,
    updated_at = now()
  RETURNING id INTO v_template_id;

  UPDATE public.training_template_versions
  SET is_current = false
  WHERE template_id = v_template_id
    AND id <> v_version_id;

  INSERT INTO public.training_template_versions (
    id,
    template_id,
    version_no,
    status,
    is_current,
    source_seed_key,
    source_packet,
    changelog,
    metadata,
    published_at
  )
  VALUES (
    v_version_id,
    v_template_id,
    1,
    'published',
    true,
    v_seed->'template'->>'source_seed_key',
    v_seed->'template'->>'source_packet',
    'Initial PCT readiness board import from workbook.',
    jsonb_build_object('import_report', v_seed->'import_report'),
    now()
  )
  ON CONFLICT (id) DO UPDATE
  SET
    status = 'published',
    is_current = true,
    source_seed_key = EXCLUDED.source_seed_key,
    source_packet = EXCLUDED.source_packet,
    changelog = EXCLUDED.changelog,
    metadata = EXCLUDED.metadata,
    published_at = COALESCE(public.training_template_versions.published_at, now());

  FOR v_section IN SELECT value FROM jsonb_array_elements(v_seed->'sections') LOOP
    INSERT INTO public.training_template_sections (
      id,
      template_version_id,
      section_key,
      title,
      section_type,
      sequence_order,
      completion_mode,
      metadata
    )
    VALUES (
      (v_section->>'id')::uuid,
      v_version_id,
      v_section->>'section_key',
      v_section->>'title',
      'checklist',
      (v_section->>'sequence_order')::integer,
      'complete_only',
      jsonb_build_object(
        'source_sheet', 'original copy',
        'source_row', (v_section->>'source_row')::integer,
        'pct_readiness_category', true
      )
    )
    ON CONFLICT (template_version_id, section_key) DO UPDATE
    SET
      title = EXCLUDED.title,
      sequence_order = EXCLUDED.sequence_order,
      metadata = EXCLUDED.metadata
    RETURNING id INTO v_section_id;

    FOR v_item IN SELECT value FROM jsonb_array_elements(v_section->'items') LOOP
      INSERT INTO public.training_template_items (
        id,
        template_version_id,
        template_section_id,
        item_key,
        label,
        description,
        item_type,
        sequence_order,
        required,
        completion_mode,
        metadata
      )
      VALUES (
        (v_item->>'id')::uuid,
        v_version_id,
        v_section_id,
        v_item->>'item_key',
        v_item->>'label',
        NULL,
        'task',
        (v_item->>'sequence_order')::integer,
        true,
        'complete_only',
        jsonb_build_object(
          'normalized_label', v_item->>'normalized_label',
          'source_sheet', v_item->>'source_sheet',
          'source_row', (v_item->>'source_row')::integer,
          'source_values', v_item->'source_values',
          'pct_readiness_task', true
        )
      )
      ON CONFLICT (template_version_id, item_key) DO UPDATE
      SET
        template_section_id = EXCLUDED.template_section_id,
        label = EXCLUDED.label,
        sequence_order = EXCLUDED.sequence_order,
        metadata = EXCLUDED.metadata;
    END LOOP;
  END LOOP;

  SELECT COUNT(*)
  INTO v_required_count
  FROM public.training_template_items
  WHERE template_version_id = v_version_id
    AND required = true;

  FOR v_trainee IN SELECT value FROM jsonb_array_elements(v_seed->'trainees') LOOP
    SELECT COUNT(*), (array_agg(e.id ORDER BY COALESCE(e.start_date, e.first_shift_date) DESC NULLS LAST, e.full_name))[1]
    INTO v_match_count, v_employee_id
    FROM public.labor_employees e
    WHERE e.employment_status = 'active'
      AND regexp_replace(lower(e.full_name), '[^a-z0-9]+', '', 'g') = replace(v_trainee->>'normalized_employee_name', ' ', '');

    IF v_match_count = 1 THEN
      SELECT *
      INTO v_employee
      FROM public.labor_employees e
      WHERE e.id = v_employee_id;

      v_match_report := jsonb_set(
        v_match_report,
        '{matched}',
        (v_match_report->'matched') || jsonb_build_array(jsonb_build_object(
          'sheet_name', v_trainee->>'sheet_name',
          'labor_employee_id', v_employee.id,
          'employee_name', v_employee.full_name,
          'location_id', v_employee.location_id
        ))
      );

      SELECT id
      INTO v_record_id
      FROM public.training_records
      WHERE template_id = v_template_id
        AND labor_employee_id = v_employee.id
        AND overall_status <> 'archived'
      ORDER BY created_at DESC
      LIMIT 1;

      IF v_record_id IS NULL THEN
        INSERT INTO public.training_records (
          template_id,
          template_version_id,
          template_name_snapshot,
          template_class_snapshot,
          labor_employee_id,
          employee_id,
          employee_name_first,
          employee_name_last,
          employee_full_name,
          target_role,
          location_id,
          hire_date,
          training_start_date,
          assigned_trainer_name,
          assigned_manager_name,
          overall_status,
          progress_percent,
          required_item_count,
          required_item_completed_count,
          template_snapshot,
          created_by_user_id,
          updated_by_user_id
        )
        VALUES (
          v_template_id,
          v_version_id,
          v_seed->'template'->>'name',
          'training_plan',
          v_employee.id,
          v_employee.id,
          split_part(v_employee.full_name, ' ', 1),
          NULLIF(btrim(substring(v_employee.full_name FROM length(split_part(v_employee.full_name, ' ', 1)) + 1)), ''),
          v_employee.full_name,
          COALESCE(NULLIF(v_employee.position_title, ''), 'PCT'),
          v_employee.location_id,
          COALESCE(v_employee.first_shift_date, v_employee.start_date),
          CURRENT_DATE,
          v_employee.assigned_trainer_name,
          v_employee.assigned_manager_name,
          'not_started',
          0,
          v_required_count,
          0,
          COALESCE(public.build_training_template_published_snapshot(v_version_id), '{}'::jsonb),
          NULL,
          NULL
        )
        RETURNING id INTO v_record_id;

        INSERT INTO public.training_record_events (
          record_id,
          event_type,
          actor_name,
          after_state
        )
        VALUES (
          v_record_id,
          'record_created',
          'PCT Workbook Import',
          jsonb_build_object(
            'template_id', v_template_id,
            'template_version_id', v_version_id,
            'source_sheet', v_trainee->>'sheet_name',
            'source_workbook', v_seed->'import_report'->>'source_workbook_name'
          )
        );
      END IF;

      INSERT INTO public.training_record_item_results (
        record_id,
        template_item_id,
        template_section_id,
        status,
        metadata
      )
      SELECT
        v_record_id,
        item.id,
        item.template_section_id,
        'not_started'::public.training_item_status,
        '{}'::jsonb
      FROM public.training_template_items item
      WHERE item.template_version_id = v_version_id
      ON CONFLICT (record_id, template_item_id) DO NOTHING;

      FOR v_result IN SELECT value FROM jsonb_array_elements(v_trainee->'results') LOOP
        SELECT item.id, item.template_section_id
        INTO v_item_id, v_section_id
        FROM public.training_template_items item
        WHERE item.template_version_id = v_version_id
          AND item.item_key = v_result->>'item_key';

        IF v_item_id IS NOT NULL THEN
          UPDATE public.training_record_item_results
          SET
            status = (v_result->>'item_status')::public.training_item_status,
            completed_by_name = CASE
              WHEN (v_result->>'item_status') IN ('complete', 'passed') THEN COALESCE(NULLIF(v_result->>'verified_by', ''), NULLIF(v_result->>'demonstrated_by', ''), completed_by_name)
              ELSE completed_by_name
            END,
            completed_at = CASE
              WHEN (v_result->>'item_status') IN ('complete', 'passed') THEN COALESCE(completed_at, now())
              ELSE completed_at
            END,
            evaluated_by_name = COALESCE(NULLIF(v_result->>'verified_by', ''), evaluated_by_name),
            metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
              'pct_readiness_status', v_result->>'readiness_status',
              'demonstrated_by_name', NULLIF(v_result->>'demonstrated_by', ''),
              'verified_by_name', NULLIF(v_result->>'verified_by', ''),
              'source_workbook', v_seed->'import_report'->>'source_workbook_name',
              'source_sheet', v_trainee->>'sheet_name',
              'source_row', (v_result->>'source_row')::integer,
              'raw_values', v_result->'raw_values',
              'match_method', v_result->>'match_method',
              'imported_at', now()
            ),
            updated_at = now()
          WHERE record_id = v_record_id
            AND template_item_id = v_item_id;

          IF NULLIF(v_result->>'note_text', '') IS NOT NULL THEN
            IF NOT EXISTS (
              SELECT 1
              FROM public.training_record_notes note
              WHERE note.record_id = v_record_id
                AND note.template_item_id = v_item_id
                AND note.note_text = v_result->>'note_text'
            ) THEN
              INSERT INTO public.training_record_notes (
                record_id,
                template_section_id,
                template_item_id,
                note_text,
                initials,
                created_by_name
              )
              VALUES (
                v_record_id,
                v_section_id,
                v_item_id,
                v_result->>'note_text',
                'PWI',
                'PCT Workbook Import'
              );
            END IF;
          END IF;
        END IF;
      END LOOP;

      PERFORM public.recalculate_pct_readiness_record(v_record_id, NULL);
    ELSIF v_match_count = 0 THEN
      v_match_report := jsonb_set(
        v_match_report,
        '{unmatched}',
        (v_match_report->'unmatched') || jsonb_build_array(jsonb_build_object(
          'sheet_name', v_trainee->>'sheet_name',
          'normalized_employee_name', v_trainee->>'normalized_employee_name'
        ))
      );
    ELSE
      v_match_report := jsonb_set(
        v_match_report,
        '{ambiguous}',
        (v_match_report->'ambiguous') || jsonb_build_array(jsonb_build_object(
          'sheet_name', v_trainee->>'sheet_name',
          'normalized_employee_name', v_trainee->>'normalized_employee_name',
          'match_count', v_match_count
        ))
      );
    END IF;

    v_record_id := NULL;
    v_item_id := NULL;
    v_section_id := NULL;
  END LOOP;

  UPDATE public.training_template_versions
  SET metadata = jsonb_set(
    metadata,
    '{import_report,employee_matching}',
    v_match_report,
    true
  )
  WHERE id = v_version_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_pct_readiness_board(
  p_location_ref text,
  p_actor_user_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
AS $$
DECLARE
  v_location_id uuid;
  v_template public.training_templates%ROWTYPE;
  v_version public.training_template_versions%ROWTYPE;
  v_sections jsonb := '[]'::jsonb;
  v_records jsonb := '[]'::jsonb;
  v_cells jsonb := '{}'::jsonb;
  v_available_employees jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
BEGIN
  v_location_id := public.resolve_labor_location_id(p_location_ref, p_actor_user_id);
  IF v_location_id IS NULL THEN
    RETURN jsonb_build_object(
      'template', NULL,
      'sections', '[]'::jsonb,
      'records', '[]'::jsonb,
      'cells', '{}'::jsonb,
      'available_employees', '[]'::jsonb,
      'summary', jsonb_build_object('total_active_pct_trainees', 0, 'average_readiness', 0, 'needs_coaching_count', 0, 'weakest_task_gaps', '[]'::jsonb),
      'import_report', '{}'::jsonb,
      'error', 'location_not_found'
    );
  END IF;

  SELECT *
  INTO v_template
  FROM public.training_templates
  WHERE slug = 'pct_team_readiness_board'
    AND is_active = true
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'template', NULL,
      'sections', '[]'::jsonb,
      'records', '[]'::jsonb,
      'cells', '{}'::jsonb,
      'available_employees', '[]'::jsonb,
      'summary', jsonb_build_object('total_active_pct_trainees', 0, 'average_readiness', 0, 'needs_coaching_count', 0, 'weakest_task_gaps', '[]'::jsonb),
      'import_report', '{}'::jsonb
    );
  END IF;

  SELECT *
  INTO v_version
  FROM public.training_template_versions
  WHERE template_id = v_template.id
    AND is_current = true
    AND status = 'published'
  ORDER BY version_no DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'template', to_jsonb(v_template),
      'sections', '[]'::jsonb,
      'records', '[]'::jsonb,
      'cells', '{}'::jsonb,
      'available_employees', '[]'::jsonb,
      'summary', jsonb_build_object('total_active_pct_trainees', 0, 'average_readiness', 0, 'needs_coaching_count', 0, 'weakest_task_gaps', '[]'::jsonb),
      'import_report', '{}'::jsonb,
      'error', 'current_version_not_found'
    );
  END IF;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', section.id,
      'section_key', section.section_key,
      'title', section.title,
      'sequence_order', section.sequence_order,
      'metadata', section.metadata,
      'items', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', item.id,
          'item_key', item.item_key,
          'label', item.label,
          'description', item.description,
          'sequence_order', item.sequence_order,
          'required', item.required,
          'metadata', item.metadata
        ) ORDER BY item.sequence_order)
        FROM public.training_template_items item
        WHERE item.template_section_id = section.id
      ), '[]'::jsonb)
    )
    ORDER BY section.sequence_order
  ), '[]'::jsonb)
  INTO v_sections
  FROM public.training_template_sections section
  WHERE section.template_version_id = v_version.id
    AND section.parent_section_id IS NULL;

  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', record.id,
      'template_id', record.template_id,
      'template_version_id', record.template_version_id,
      'labor_employee_id', record.labor_employee_id,
      'employee_full_name', record.employee_full_name,
      'target_role', record.target_role,
      'hire_date', record.hire_date,
      'training_start_date', record.training_start_date,
      'target_end_date', record.target_end_date,
      'overall_status', record.overall_status,
      'progress_percent', record.progress_percent,
      'required_item_count', record.required_item_count,
      'required_item_completed_count', record.required_item_completed_count,
      'updated_at', record.updated_at,
      'employee', CASE WHEN employee.id IS NULL THEN NULL ELSE jsonb_build_object(
        'id', employee.id,
        'full_name', employee.full_name,
        'position_title', employee.position_title,
        'employment_status', employee.employment_status,
        'start_date', employee.start_date,
        'first_shift_date', employee.first_shift_date,
        'end_date', employee.end_date
      ) END
    )
    ORDER BY COALESCE(employee.start_date, record.training_start_date, record.created_at::date) DESC NULLS LAST, record.employee_full_name
  ), '[]'::jsonb)
  INTO v_records
  FROM public.training_records record
  LEFT JOIN public.labor_employees employee ON employee.id = record.labor_employee_id
  WHERE record.location_id = v_location_id
    AND record.template_id = v_template.id
    AND record.overall_status <> 'archived';

  WITH cell_rows AS (
    SELECT
      result.record_id,
      result.template_item_id,
      result.template_section_id,
      result.status,
      COALESCE(result.metadata->>'pct_readiness_status', CASE
        WHEN result.status IN ('complete', 'passed') THEN 'verified'
        WHEN result.status = 'in_progress' THEN 'demonstrated'
        ELSE result.status::text
      END) AS readiness_status,
      result.completed_by_name,
      result.completed_at,
      result.evaluated_by_name,
      result.updated_at,
      result.metadata,
      (
        SELECT note.note_text
        FROM public.training_record_notes note
        WHERE note.record_id = result.record_id
          AND note.template_item_id = result.template_item_id
        ORDER BY note.created_at DESC
        LIMIT 1
      ) AS latest_note,
      (
        SELECT note.created_at
        FROM public.training_record_notes note
        WHERE note.record_id = result.record_id
          AND note.template_item_id = result.template_item_id
        ORDER BY note.created_at DESC
        LIMIT 1
      ) AS latest_note_at,
      (
        SELECT COALESCE(NULLIF(note.created_by_name, ''), NULLIF(note.initials, ''))
        FROM public.training_record_notes note
        WHERE note.record_id = result.record_id
          AND note.template_item_id = result.template_item_id
        ORDER BY note.created_at DESC
        LIMIT 1
      ) AS latest_note_actor_name,
      (
        SELECT NULLIF(event.actor_name, '')
        FROM public.training_record_events event
        WHERE event.record_id = result.record_id
          AND event.template_item_id = result.template_item_id
          AND event.event_type = 'item_status_changed'
        ORDER BY event.created_at DESC
        LIMIT 1
      ) AS latest_status_actor_name,
      (
        SELECT event.created_at
        FROM public.training_record_events event
        WHERE event.record_id = result.record_id
          AND event.template_item_id = result.template_item_id
          AND event.event_type = 'item_status_changed'
        ORDER BY event.created_at DESC
        LIMIT 1
      ) AS latest_status_actor_at
    FROM public.training_record_item_results result
    JOIN public.training_records record ON record.id = result.record_id
    WHERE record.location_id = v_location_id
      AND record.template_id = v_template.id
      AND record.overall_status <> 'archived'
  )
  SELECT COALESCE(jsonb_object_agg(
    record_id::text || ':' || template_item_id::text,
    jsonb_build_object(
      'record_id', record_id,
      'template_item_id', template_item_id,
      'template_section_id', template_section_id,
      'status', status,
      'readiness_status', readiness_status,
      'demonstrated_by', metadata->>'demonstrated_by_name',
      'verified_by', metadata->>'verified_by_name',
      'completed_by_name', completed_by_name,
      'completed_at', completed_at,
      'evaluated_by_name', evaluated_by_name,
      'updated_at', updated_at,
      'latest_note', latest_note,
      'latest_note_at', latest_note_at,
      'latest_note_actor_name', latest_note_actor_name,
      'latest_status_actor_name', latest_status_actor_name,
      'latest_status_actor_at', latest_status_actor_at,
      'metadata', metadata
    )
  ), '{}'::jsonb)
  INTO v_cells
  FROM cell_rows;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', employee.id,
    'full_name', employee.full_name,
    'position_title', employee.position_title,
    'employment_status', employee.employment_status,
    'start_date', employee.start_date,
    'first_shift_date', employee.first_shift_date,
    'assigned_trainer_name', employee.assigned_trainer_name,
    'assigned_manager_name', employee.assigned_manager_name
  ) ORDER BY COALESCE(employee.start_date, employee.first_shift_date) DESC NULLS LAST, employee.full_name), '[]'::jsonb)
  INTO v_available_employees
  FROM public.labor_employees employee
  WHERE employee.location_id = v_location_id
    AND employee.employment_status = 'active'
    AND NOT EXISTS (
      SELECT 1
      FROM public.training_records record
      WHERE record.template_id = v_template.id
        AND record.labor_employee_id = employee.id
        AND record.overall_status <> 'archived'
    );

  WITH records_for_board AS (
    SELECT record.id, record.progress_percent
    FROM public.training_records record
    WHERE record.location_id = v_location_id
      AND record.template_id = v_template.id
      AND record.overall_status <> 'archived'
  ), cell_summary AS (
    SELECT
      result.template_item_id,
      item.template_section_id,
      item.label,
      section.title AS category,
      COALESCE(result.metadata->>'pct_readiness_status', CASE
        WHEN result.status IN ('complete', 'passed') THEN 'verified'
        WHEN result.status = 'in_progress' THEN 'demonstrated'
        ELSE result.status::text
      END) AS readiness_status
    FROM public.training_record_item_results result
    JOIN public.training_records record ON record.id = result.record_id
    JOIN public.training_template_items item ON item.id = result.template_item_id
    JOIN public.training_template_sections section ON section.id = item.template_section_id
    WHERE record.location_id = v_location_id
      AND record.template_id = v_template.id
      AND record.overall_status <> 'archived'
  ), weak_tasks AS (
    SELECT
      template_item_id,
      label,
      category,
      COUNT(*) FILTER (WHERE readiness_status NOT IN ('verified', 'waived')) AS gap_count,
      COUNT(*) AS trainee_count
    FROM cell_summary
    GROUP BY template_item_id, label, category
    HAVING COUNT(*) FILTER (WHERE readiness_status NOT IN ('verified', 'waived')) > 0
    ORDER BY gap_count DESC, label
    LIMIT 5
  )
  SELECT jsonb_build_object(
    'total_active_pct_trainees', (SELECT COUNT(*) FROM records_for_board),
    'average_readiness', COALESCE((SELECT ROUND(AVG(progress_percent)::numeric, 1) FROM records_for_board), 0),
    'needs_coaching_count', COALESCE((SELECT COUNT(*) FROM cell_summary WHERE readiness_status = 'needs_coaching'), 0),
    'weakest_task_gaps', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'template_item_id', template_item_id,
      'label', label,
      'category', category,
      'gap_count', gap_count,
      'trainee_count', trainee_count
    )) FROM weak_tasks), '[]'::jsonb)
  )
  INTO v_summary;

  RETURN jsonb_build_object(
    'template', to_jsonb(v_template) || jsonb_build_object('current_version', to_jsonb(v_version)),
    'sections', v_sections,
    'records', v_records,
    'cells', v_cells,
    'available_employees', v_available_employees,
    'summary', v_summary,
    'import_report', COALESCE(v_version.metadata->'import_report', '{}'::jsonb)
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.create_pct_readiness_record(
  p_labor_employee_id uuid,
  p_location_ref text,
  p_actor_user_id uuid DEFAULT NULL,
  p_actor_name text DEFAULT NULL
)
RETURNS public.training_records
LANGUAGE plpgsql
AS $$
DECLARE
  v_location_id uuid;
  v_employee public.labor_employees%ROWTYPE;
  v_template public.training_templates%ROWTYPE;
  v_existing_id uuid;
  v_record public.training_records%ROWTYPE;
BEGIN
  IF p_labor_employee_id IS NULL THEN
    RAISE EXCEPTION 'Labor employee is required';
  END IF;

  v_location_id := public.resolve_labor_location_id(p_location_ref, p_actor_user_id);
  IF v_location_id IS NULL THEN
    RAISE EXCEPTION 'Unable to resolve location from %', p_location_ref;
  END IF;

  SELECT *
  INTO v_employee
  FROM public.labor_employees
  WHERE id = p_labor_employee_id
    AND location_id = v_location_id
    AND employment_status = 'active';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Active labor employee % was not found for location %', p_labor_employee_id, v_location_id;
  END IF;

  SELECT *
  INTO v_template
  FROM public.training_templates
  WHERE slug = 'pct_team_readiness_board'
    AND is_active = true
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PCT readiness template is not installed';
  END IF;

  SELECT id
  INTO v_existing_id
  FROM public.training_records
  WHERE template_id = v_template.id
    AND labor_employee_id = v_employee.id
    AND overall_status <> 'archived'
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    RAISE EXCEPTION 'Active PCT readiness record already exists for %', v_employee.full_name;
  END IF;

  SELECT *
  INTO v_record
  FROM public.create_training_record(
    v_template.id,
    v_location_id::text,
    v_employee.full_name,
    COALESCE(NULLIF(v_employee.position_title, ''), 'PCT'),
    COALESCE(v_employee.first_shift_date, v_employee.start_date),
    CURRENT_DATE,
    NULL,
    v_employee.assigned_trainer_name,
    p_actor_user_id,
    p_actor_name,
    v_employee.assigned_manager_name,
    v_employee.id
  );

  UPDATE public.training_record_item_results result
  SET metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('pct_readiness_status', 'not_started')
  WHERE result.record_id = v_record.id;

  RETURN public.recalculate_pct_readiness_record(v_record.id, p_actor_user_id);
END;
$$;

CREATE OR REPLACE FUNCTION public.update_pct_readiness_cell(
  p_record_id uuid,
  p_template_item_id uuid,
  p_readiness_status text,
  p_demonstrated_by text DEFAULT NULL,
  p_verified_by text DEFAULT NULL,
  p_comment text DEFAULT NULL,
  p_actor_user_id uuid DEFAULT NULL,
  p_actor_name text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
AS $$
DECLARE
  v_record public.training_records%ROWTYPE;
  v_result public.training_record_item_results%ROWTYPE;
  v_before jsonb;
  v_readiness_status text := lower(regexp_replace(trim(COALESCE(p_readiness_status, 'not_started')), '[^a-z0-9]+', '_', 'g'));
  v_item_status public.training_item_status;
  v_actor_name text := COALESCE(NULLIF(trim(COALESCE(p_actor_name, '')), ''), 'System');
  v_note_text text := NULLIF(trim(COALESCE(p_comment, '')), '');
  v_updated_record public.training_records%ROWTYPE;
BEGIN
  IF v_readiness_status IN ('verified', 'qualified', 'verified_qualified') THEN
    v_readiness_status := 'verified';
    v_item_status := 'complete';
  ELSIF v_readiness_status = 'demonstrated' THEN
    v_item_status := 'in_progress';
  ELSIF v_readiness_status = 'needs_coaching' THEN
    v_item_status := 'needs_coaching';
  ELSIF v_readiness_status = 'blocked' THEN
    v_item_status := 'blocked';
  ELSIF v_readiness_status = 'waived' THEN
    v_item_status := 'waived';
  ELSIF v_readiness_status = 'not_started' THEN
    v_item_status := 'not_started';
  ELSE
    RAISE EXCEPTION 'Unsupported PCT readiness status %', p_readiness_status;
  END IF;

  SELECT record.*
  INTO v_record
  FROM public.training_records record
  JOIN public.training_templates template ON template.id = record.template_id
  WHERE record.id = p_record_id
    AND template.slug = 'pct_team_readiness_board'
    AND record.overall_status <> 'archived';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PCT readiness record % was not found', p_record_id;
  END IF;

  SELECT *
  INTO v_result
  FROM public.training_record_item_results
  WHERE record_id = p_record_id
    AND template_item_id = p_template_item_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PCT readiness item % was not found for record %', p_template_item_id, p_record_id;
  END IF;

  v_before := to_jsonb(v_result);

  UPDATE public.training_record_item_results
  SET
    status = v_item_status,
    completed_by_user_id = CASE WHEN v_item_status IN ('complete', 'passed', 'waived') THEN p_actor_user_id ELSE NULL END,
    completed_by_name = CASE WHEN v_item_status IN ('complete', 'passed', 'waived') THEN COALESCE(NULLIF(trim(COALESCE(p_verified_by, '')), ''), NULLIF(trim(COALESCE(p_demonstrated_by, '')), ''), v_actor_name) ELSE NULL END,
    completed_at = CASE WHEN v_item_status IN ('complete', 'passed', 'waived') THEN COALESCE(completed_at, now()) ELSE NULL END,
    evaluated_by_name = COALESCE(NULLIF(trim(COALESCE(p_verified_by, '')), ''), NULLIF(trim(COALESCE(p_demonstrated_by, '')), ''), evaluated_by_name),
    metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
      'pct_readiness_status', v_readiness_status,
      'demonstrated_by_name', NULLIF(trim(COALESCE(p_demonstrated_by, '')), ''),
      'verified_by_name', NULLIF(trim(COALESCE(p_verified_by, '')), ''),
      'last_updated_by_name', v_actor_name,
      'last_updated_by_user_id', p_actor_user_id,
      'last_updated_at', now()
    ),
    updated_at = now()
  WHERE id = v_result.id
  RETURNING * INTO v_result;

  IF v_note_text IS NOT NULL THEN
    INSERT INTO public.training_record_notes (
      record_id,
      template_section_id,
      template_item_id,
      note_text,
      initials,
      created_by_user_id,
      created_by_name
    )
    VALUES (
      p_record_id,
      v_result.template_section_id,
      p_template_item_id,
      v_note_text,
      public.labor_initials(v_actor_name),
      p_actor_user_id,
      v_actor_name
    );
  END IF;

  v_updated_record := public.recalculate_pct_readiness_record(p_record_id, p_actor_user_id);

  INSERT INTO public.training_record_events (
    record_id,
    template_item_id,
    event_type,
    actor_user_id,
    actor_name,
    before_state,
    after_state
  )
  VALUES (
    p_record_id,
    p_template_item_id,
    'item_status_changed',
    p_actor_user_id,
    v_actor_name,
    v_before,
    to_jsonb(v_result)
  );

  RETURN jsonb_build_object(
    'result', to_jsonb(v_result),
    'record', to_jsonb(v_updated_record)
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_pct_readiness_board(text, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.create_pct_readiness_record(uuid, text, uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.update_pct_readiness_cell(uuid, uuid, text, text, text, text, uuid, text) TO authenticated;
